def findMaximumNum(str, K):
    def swap(s, i, j):
        s = list(s)
        s[i], s[j] = s[j], s[i]
        return ''.join(s)

    def findMaxUtil(str, k, res):
        if k == 0:
            return

        n = len(str)
        for i in range(n - 1):
            for j in range(i + 1, n):
                if str[i] < str[j]:
                    new_str = swap(str, i, j)
                    if new_str > res[0]:
                        res[0] = new_str
                    findMaxUtil(new_str, k - 1, res)

    res = [str]
    findMaxUtil(str, K, res)
    return res[0]

